import{z as l,x as A,o,c as C,q as r,j as n,D as e,d as t,s as B,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"共识与 2PC","description":"","frontmatter":{"title":"共识与 2PC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/consensus-vs-2pc.md","filePath":"cs/consensus-vs-2pc.md","lastUpdated":1791413859000}'),m={name:"cs/consensus-vs-2pc.md"};function p(d,a,P,c,D,u){const s=A("Mermaid");return o(),C("div",null,[a[2]||(a[2]=r('<h1 id="共识与-2pc" tabindex="-1">共识与 2PC <a class="header-anchor" href="#共识与-2pc" aria-label="Permalink to &quot;共识与 2PC&quot;">​</a></h1><div class="epigraph"><p>两阶段提交让所有资源管理器同提交或同中止，但协调者崩溃会阻塞。共识复制的是决策日志，换主可以继续；2PC 复制的不是那条日志。</p><footer>—— 据 Gray and Reuter, Transaction Processing；Lamport, Paxos Made Simple；Skeen, Nonblocking Commit Protocols 整理</footer></div><p>上一课<a href="/cs/pbft">PBFT</a>把法定人数决策做到撒谎档。缺口是<strong>事务提交协议常被误叫共识</strong>：2PC 的参与者对「commit/abort」要一致，但经典 2PC 有单点阻塞，不满足<a href="/cs/flp-impossibility">FLP</a>语境下「正确节点终决定」——它根本没打算在协调者死时终止。本课拆开。不重写 prepare/accept。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2PC：协调者问 canCommit，全部是则 commit，否则 abort。参与者在准备后进入不确定态，必须等协调者。协调者在发出 commit 前崩溃：参与者阻塞。<span class="marginnote">2PC 可以类比一场婚礼：司仪先问全场「有异议吗」（canCommit），没人反对才宣布成婚（commit）。可若司仪在问完之后、宣布之前晕倒，全场宾客只能干站着——谁也无权代为宣布。这就是「不确定态阻塞」：票已交出，结局却悬在协调者手里。</span>这是原子提交，规格是「全员同结果」，假设是崩溃恢复+最终协调者回来或人工。</p><p>共识（Paxos）：多数派活着即可选定值，少数派阻塞不影响已选定值的学习者。缺口：原子提交在存在故障时有已知困难（Skeen 非阻塞提交需要更多轮与更多活节点假设）。把 2PC 当 Paxos 会在协调者死时把整个事务卡住，还以为「有共识」。</p><p><span class="marginnote">Gray 的事务教材把 2PC 当恢复协议。Paxos-Commit 一类工作用共识选 commit/abort，消除单协调者阻塞，那是混合，不是经典 2PC。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>需要跨分片原子：要么阻塞式 2PC（短事务、协调者高可用），要么把提交记录写进<a href="/cs/replicated-state-machine">RSM</a>（协调者本身是多数派）。需要给配置/锁一个值：直接共识，不要 2PC。</p>',9)),(o(),n(i,null,{default:e(()=>[B(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACM%5B%22%E5%8E%9F%E5%AD%90%E6%8F%90%E4%BA%A4%3A%20%E5%85%A8%E5%91%98%E5%90%8C%20commit%2Fabort%22%5D%20--%3E%20TPC%5B%222PC%3A%20%E5%8D%8F%E8%B0%83%E8%80%85%E5%8F%AF%E9%98%BB%E5%A1%9E%22%5D%0A%20%20ACM%20--%3E%20PC%5B%22Paxos-Commit%20%E7%AD%89%22%5D%0A%20%20CONS%5B%22%E5%85%B1%E8%AF%86%3A%20%E5%A4%9A%E6%95%B0%E6%B4%BE%E9%80%89%E5%AE%9A%E4%B8%80%E5%80%BC%22%5D%20--%3E%20LOG%5B%22RSM%20%E6%97%A5%E5%BF%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"3PC 减少部分阻塞，在异步网络仍有坑；本课点名，不展开状态表。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[t("2PC 的「多数」不是法定人数相交：它要"),E("strong",null,"全体"),t("准备成功才提交，一个慢盘就能中止或拖死。共识的多数是为了在 \\(f\\lt n/2\\) 崩溃下仍选定。对象不同：2PC 对象是事务结局；Paxos 对象是槽里的字节。")],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"给个数字实例：\\(n=5\\) 个参与者时，2PC 要收齐 5 张 yes 才敢提交——1 个投 no 或超时，全体 abort；而 Paxos 在容忍 \\(f=2\\) 故障（\\(n=5\\)）下，只要 \\(f+1=3\\) 个节点活着就能选出值。「全员同意」与「多数派同意」的差距，就是可用性的差距。")],-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"初学者容易以为「用了 2PC 就有一致性了」，实际上 2PC 只保证各分片同 commit 或同 abort：它不给寄存器线性一致，也不保证故障时能前进——协调者一死整个事务悬在半空，最后往往靠人工或真共识来解围。")],-1)),a[8]||(a[8]=E("p",null,"数据库课的事务与 WAL 仍在：2PC 是跨资源管理器的补丁。分布式课到这里才把它和复制日志分开，避免「我们用了 2PC 所以线性一致」——2PC 不给寄存器线性一致，只给参与者原子结局，且可阻塞。",-1)),(o(),n(i,null,{default:e(()=>[B(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q1%5B%22%E9%98%B6%E6%AE%B5%E4%B8%80%EF%BC%9A%E5%8D%8F%E8%B0%83%E8%80%85%E5%8F%91%20canCommit%22%5D%20--%3E%20YES%5B%22%E5%8F%82%E4%B8%8E%E8%80%85%E6%8A%95%20yes%EF%BC%8C%E9%94%81%E4%BD%8F%E8%B5%84%E6%BA%90%22%5D%0A%20%20YES%20--%3E%20UNC%5B%22%E4%B8%8D%E7%A1%AE%E5%AE%9A%E6%80%81%EF%BC%9A%E7%BB%93%E5%B1%80%E5%8F%AA%E7%94%B1%E5%8D%8F%E8%B0%83%E8%80%85%E6%8E%8C%E6%8F%A1%22%5D%0A%20%20Q1%20--%3E%20NOV%5B%22%E6%9C%89%E5%8F%82%E4%B8%8E%E8%80%85%E6%8A%95%20no%20%E6%88%96%E8%B6%85%E6%97%B6%22%5D%0A%20%20NOV%20--%3E%20AB%5B%22%E5%85%A8%E5%91%98%20abort%EF%BC%8C%E7%AB%8B%E5%88%BB%E8%A7%A3%E9%99%A4%22%5D%0A%20%20UNC%20--%3E%20Q2%5B%22%E9%98%B6%E6%AE%B5%E4%BA%8C%EF%BC%9A%E5%8D%8F%E8%B0%83%E8%80%85%E5%B9%BF%E6%92%AD%20commit%2Fabort%22%5D%0A%20%20Q2%20--%3E%20REL%5B%22%E6%94%B6%E5%88%B0%E8%A3%81%E5%86%B3%EF%BC%9A%E8%A7%A3%E9%94%81%EF%BC%8C%E4%BA%8B%E5%8A%A1%E4%BA%86%E7%BB%93%22%5D%0A%20%20CRASH%5B%22%E5%8D%8F%E8%B0%83%E8%80%85%E5%9C%A8%E9%98%B6%E6%AE%B5%E4%BA%8C%E4%B9%8B%E5%89%8D%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20STUCK%5B%22%E6%8A%95%E8%BF%87%20yes%20%E7%9A%84%E5%85%A8%E4%BD%93%E5%8D%A1%E6%AD%BB%EF%BC%8C%E7%AD%89%E5%8D%8F%E8%B0%83%E8%80%85%E5%A4%8D%E6%B4%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=r('<p>本课不重写隔离级别。也不把 Saga 补偿当 2PC（后课系统模式）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不画 2PC 全部超时状态。不引入 XA 接口清单。后课默认：阻塞原子提交 ≠ 共识；要故障下仍前进，把决策放进 Paxos/Raft 日志。领导者选举下一课处理「谁当协调者/主」的脑裂，那是另一坑。</p><p>全员同意比多数派同意更脆。脆的协议不能靠改名变强壮。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>2PC：原子提交，协调者崩溃阻塞。</li><li>共识：多数派选定值，换提议者可继续。</li><li>高可用提交 = 用共识复制 commit 决策，不是裸 2PC。</li><li>出处：Gray and Reuter；Lamport 2001；Skeen 非阻塞提交。</li></ul>',6))])}const b=l(m,[["render",p]]);export{f as __pageData,b as default};
